"""Object storage for uploaded files.

Callers use ``get_storage()`` and the three methods of ``Storage``; they
never touch paths. ``LocalStorage`` writes to ``settings.media_root``, a
Docker volume in development. An S3/MinIO backend only needs to implement
the same methods and be selected with ``STORAGE_BACKEND``.
"""

import os
import re
from pathlib import Path
from typing import Protocol

from app.core.config import settings

# Keys are generated by the server (uuid + extension), never by clients.
KEY_PATTERN = re.compile(r"^[0-9a-f]{32}\.(png|jpg|webp|gif)$")


class Storage(Protocol):
    def save(self, key: str, data: bytes) -> None: ...

    def open(self, key: str) -> bytes | None: ...

    def delete(self, key: str) -> None: ...


class LocalStorage:
    def __init__(self, root: str):
        self.root = Path(root)

    def _path(self, key: str) -> Path:
        if not KEY_PATTERN.match(key):
            raise ValueError("Invalid storage key.")
        return self.root / key[:2] / key

    def save(self, key: str, data: bytes) -> None:
        path = self._path(key)
        path.parent.mkdir(parents=True, exist_ok=True)
        temporary = path.with_suffix(path.suffix + ".part")
        temporary.write_bytes(data)
        os.replace(temporary, path)

    def open(self, key: str) -> bytes | None:
        try:
            return self._path(key).read_bytes()
        except (FileNotFoundError, ValueError):
            return None

    def delete(self, key: str) -> None:
        try:
            self._path(key).unlink()
        except (FileNotFoundError, ValueError):
            pass


def get_storage() -> Storage:
    if settings.storage_backend == "local":
        return LocalStorage(settings.media_root)
    raise RuntimeError(f"Unknown storage backend: {settings.storage_backend}")
